import { execution } from '@dynatrace-sdk/automation-utils';


export default async function ({ execution_id }) {
  const exec = await execution(execution_id);

  const ex = await fetch(`/platform/automation/v1/executions/${execution_id}`);
  const data = await ex.json();
  const event = data.params?.event || {};
  const problemTitle = event['event.name'] || 'Unknown problem';
  const problemId = event['event.id'] || 'N/A';
  const status = event['event.status'] || 'OPEN';
  const affectedEntities = (event['affected_entity_ids'] || []).join(', ') || 'N/A';
  const rootCause = event['root_cause_entity_name'] || 'Unknown';
  const startTime = event['event.start'] || new Date().toISOString();
  const dtUrl = event['dt.davis.mute_url']?.replace('/mute', '') || '';
  const deployment = await exec.result('fetch_event_details');
  console.log(deployment.records[0]["lookup.deployment.url"])

  return {
    deploymentUrl: deployment.records[0]["lookup.deployment.url"],
    problemTitle,
    problemId,
    status,
    affectedEntities,
    rootCause,
    startTime,
    dtUrl
  };
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ execution_id }) {
  const exec = await execution(execution_id);
  const result = await exec.result('extract_event_details');

  // ↓↓↓ paste from your VM's overview notebook ↓↓↓
  const GITEA_USER = "userN";
  const GITEA_PAT  = "<your Gitea PAT>";
  // ↑↑↑ paste from your VM's overview notebook ↑↑↑

  // Which bad-release pipeline to rollback. Match the service that's
  // failing in your VM:
  const WORKFLOW_FILE = "bad-release-payment-service.yaml";
  // Alternatives:
  //   "bad-release-order-service.yaml"
  //   "bad-release-inventory-service.yaml"

  // deploymentUrl looks like:
  //   "https://gitea.34.140.133.0.nip.io/user1/quickcart/actions/runs/3"
  // Pull the base URL ("https://gitea.<ip>.nip.io") + owner/repo from it so
  // the same workflow works no matter which VM fired the event.
  const m = result.deploymentUrl.match(
    /^(https?:\/\/[^/]+)\/([^/]+)\/([^/]+)\/actions\/runs\/\d+/
  );
  if (!m) {
    throw new Error(`Could not parse deploymentUrl: ${result.deploymentUrl}`);
  }
  const [, giteaBase, owner, repo] = m;

  // Gitea 1.25 exposes /actions/workflows/<file>/dispatches (workflow_dispatch)
  // but NOT the repository_dispatch route. The bad-release workflow handles
  // both events identically when given action=rollback, so this is the
  // straightforward path on this Gitea version.
  const url = `${giteaBase}/api/v1/repos/${owner}/${repo}/actions/workflows/${WORKFLOW_FILE}/dispatches`;
  const auth = "Basic " + btoa(`${GITEA_USER}:${GITEA_PAT}`);

  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Accept":        "application/json",
      "Content-Type":  "application/json",
      "Authorization": auth,
    },
    body: JSON.stringify({
      ref: "main",
      inputs: {
        action: "rollback",
      },
    }),
  });

  const text = await response.text();
  console.log(`Gitea workflow_dispatch ${response.status}: ${text}`);

  return {
    status:   response.status,
    success:  response.status === 204,
    giteaBase, owner, repo, workflowFile: WORKFLOW_FILE,
    body:     text,
  };
}
